__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"RODAPE_ARTIGOS",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"ARTIGOS",{enumerable:!0,get:function(){return s}});const o='Conte\xfado educativo, n\xe3o substitui acompanhamento profissional. Revisado por [psic\xf3logo respons\xe1vel \xb7 CRP a definir].',s=[{id:'fissura',titulo:'O que \xe9 a fissura e por que ela passa',resumo:'A vontade forte parece que vai durar para sempre. Ela n\xe3o dura.',minutos:3,paragrafos:['Fissura \xe9 aquela vontade intensa que aparece de repente e parece ocupar a cabe\xe7a inteira. Ela \xe9 uma rea\xe7\xe3o do corpo e do c\xe9rebro a um costume antigo, e n\xe3o um sinal de fraqueza.','A boa not\xedcia \xe9 que a fissura se comporta como uma onda. Ela sobe, chega num pico e desce. Na maioria das vezes, o pico passa em poucos minutos, mesmo quando parece que n\xe3o vai passar.','O que ajuda \xe9 atravessar o pico sem brigar com ele. Respirar devagar, mudar de lugar, beber \xe1gua ou falar com algu\xe9m d\xe1 tempo para a onda baixar.','Cada vez que voc\xea atravessa uma onda, o c\xe9rebro aprende que d\xe1 para sentir a vontade sem obedecer a ela. Com o tempo, as ondas tendem a ficar menores e mais espa\xe7adas.']},{id:'gatilhos',titulo:'Gatilhos: como descobrir os seus',resumo:'Lugares, hor\xe1rios e sentimentos que puxam o h\xe1bito. D\xe1 para mapear.',minutos:4,paragrafos:['Gatilho \xe9 tudo aquilo que costuma vir antes do h\xe1bito: um hor\xe1rio, um lugar, uma pessoa, um sentimento. T\xe9dio \xe0 noite, estresse depois do trabalho e celular na cama s\xe3o exemplos comuns.','Para descobrir os seus, observe sem julgar. Quando a vontade aparecer, anote rapidinho onde voc\xea estava, o que estava sentindo e o que tinha acabado de acontecer.','Depois de alguns dias, os padr\xf5es aparecem. \xc9 como desenhar um mapa das \xe1reas de mar agitado.','Com o mapa em m\xe3os, d\xe1 para planejar: evitar algumas rotas, preparar uma alternativa para outras e chegar mais preparado nas horas dif\xedceis.']},{id:'tropecar',titulo:'Trope\xe7ar n\xe3o apaga o que voc\xea construiu',resumo:'Uma onda forte n\xe3o desfaz as milhas que voc\xea j\xe1 navegou.',minutos:3,paragrafos:['Quase toda mudan\xe7a de h\xe1bito tem idas e vindas. Um trope\xe7o n\xe3o significa voltar para o come\xe7o. Tudo o que voc\xea aprendeu continua com voc\xea.','O pensamento de "j\xe1 que errei, tanto faz" \xe9 uma armadilha comum. Ele transforma uma onda num temporal. O caminho mais leve \xe9 olhar para o que aconteceu com curiosidade.','Pergunte: o que veio antes? O que eu estava sentindo? O que posso fazer diferente da pr\xf3xima vez? Essas respostas ajustam a rota.','No Leme, os seus dias cuidados e o seu n\xedvel n\xe3o somem quando voc\xea trope\xe7a. A gente s\xf3 ajusta a meta para ela caber na semana que voc\xea est\xe1 vivendo.']},{id:'contar',titulo:'Como contar para algu\xe9m de confian\xe7a',resumo:'Ter uma pessoa por perto faz a viagem ficar mais leve.',minutos:4,paragrafos:['Contar para algu\xe9m pode dar medo, mas costuma aliviar. Voc\xea n\xe3o precisa contar tudo de uma vez nem para todo mundo.','Escolha uma pessoa que costuma ouvir sem julgar. Pode ser um amigo, algu\xe9m da fam\xedlia ou um profissional.','Comece simples: "Estou cuidando de um h\xe1bito que tem pesado para mim. Queria que voc\xea soubesse." Depois diga como ela pode ajudar, por exemplo mandando uma mensagem \xe0 noite.','Se a conversa n\xe3o sair como voc\xea esperava, tudo bem. Isso diz mais sobre o momento da outra pessoa do que sobre voc\xea. D\xe1 para tentar com outra pessoa.']},{id:'sono-humor',titulo:'Sono, humor e vontade: tudo conectado',resumo:'Noites mal dormidas deixam as ondas mais fortes no dia seguinte.',minutos:3,paragrafos:['Quando a gente dorme pouco, o c\xe9rebro fica com menos freio e mais busca por recompensa r\xe1pida. Por isso a vontade costuma bater mais forte no dia seguinte a uma noite ruim.','Cuidar do sono \xe9 uma das formas mais simples de deixar o mar mais calmo. Hor\xe1rio parecido para deitar, luz baixa \xe0 noite e celular longe da cama j\xe1 ajudam.','Se o sono estiver muito dif\xedcil por muitas semanas, vale conversar com um profissional de sa\xfade.']}]},781,[]);
